use aktor::*;
use aktor::listener::channel;
fn main() {
    let calls: usize = std::env::var("CALLS").unwrap().parse().unwrap();
    tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap().block_on(async {
        let (handle, mut listener) = channel::<u64>(1).unwrap();
        let mut state = 0;
        let mut sum = 0;
        for _ in 0..calls {
            let reply = message::call_async(&handle, async |state: &mut u64, by| { *state += by; *state }, 1).send().await;
            listener.recv().await.unwrap().run(&mut state).await;
            sum += reply.await;
        }
        assert_eq!(sum, calls as u64 * (calls as u64 + 1) / 2);
    });
}
